929	async function beginRoomHeadAdvance(
930		authority: V3RoomHeadAuthority,
931		scope: V3RoomHeadScope,
932		current: V3RoomHead,
933		next: V3RoomHead
934	): Promise<V3RoomHeadState> {
935		if (
936			current.objectId !== scope.objectId ||
937			next.objectId !== scope.objectId ||
938			next.epoch !== current.epoch + 1 ||
939			next.currentAnchorDigest === current.currentAnchorDigest
940		) {
941			return roomHeadFailure("D110C_FLOOR_REGRESSION");
942		}
943		const observed = await readRoomHeadAuthority(authority, scope);
944		if (observed.pending !== null) {
945			if (sameRoomHead(observed.pending.previous, current) && sameRoomHead(observed.pending.next, next)) return observed;
946			return roomHeadFailure("D110C_FLOOR_PENDING_INVALID");
947		}
948		if (!sameRoomHead(observed.stable, current)) {
949			return roomHeadFailure(observed.stable.epoch > current.epoch ? "D110C_FLOOR_HEAD_AHEAD" : "D110C_FLOOR_MISMATCH");
950		}
951		const expected = Object.freeze({ pending: null, stable: current });
952		const selected = await callRoomHeadAuthority(() => authority.begin(Object.freeze({ expected, next, scope })), scope);
953		const pending = Object.freeze({ next, previous: current });
954		const desired = Object.freeze({ pending, stable: current });
955		if (selected === null || !sameRoomHeadState(selected, desired)) return roomHeadFailure("D110C_FLOOR_CONFLICT");
956		return selected;
957	}
